1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    @Autowired
31	    protected OwnerRepository ownerRepository;
32	
33	    @Mapping(target = "displayName",
34	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "initials",
36	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
37	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
38	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
39	    @Mapping(target = "locality", expression = "java(locality(owner))")
40	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
41	    public abstract OwnerDto toOwnerDto(Owner owner);
42	
43	    /**
44	     * Fixed city-to-region table: the owner's canonical region derived from its city.
45	     */
46	    static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
47	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
48	
49	    /**
50	     * Derives the owner's {@code locality} from its city using the fixed city-to-region
51	     * table ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}), returning the canonical
52	     * region string, or {@code "UNKNOWN"} when the city is not in the table.
53	     */
54	    protected String locality(Owner owner) {
55	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
56	    }
57	
58	    /**
59	     * A household of at least this many owners sharing the same {@code householdId} earns the
60	     * {@code "GOLD"} tier.
61	     */
62	    private static final int GOLD_HOUSEHOLD_SIZE = 3;
63	
64	    /**
65	     * Returns the owner's membership tier: {@code "GOLD"} when the owner belongs to a household
66	     * (owners sharing the same {@code householdId}) of at least {@value #GOLD_HOUSEHOLD_SIZE}
67	     * members; otherwise {@code "SILVER"} when the owner has no namesakes (namesakeCount is 0) and
68	     * an email address is present, else {@code "BRONZE"}.
69	     */
70	    protected String membershipTier(Owner owner) {
71	        String householdId = owner.getHouseholdId();
72	        if (householdId != null && !householdId.isBlank()) {
73	            long members = ownerRepository.findAll().stream()
74	                    .filter(existing -> householdId.equals(existing.getHouseholdId()))
75	                    .count();
76	            if (members >= GOLD_HOUSEHOLD_SIZE) {
77	                return "GOLD";
78	            }
79	        }
80	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
81	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
82	        return (noNamesakes && hasEmail) ? "SILVER" : "BRONZE";
83	    }
84	
85	    /**
86	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of
87	     * the registrationDate year (e.g. 'SMI-0007-M26'). Returns {@code null} when either the
88	     * customer code or the registration date is absent (e.g. legacy seed owners).
89	     */
90	    protected String membershipNumber(Owner owner) {
91	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
92	            return null;
93	        }
94	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
95	    }
96	
97	    /**
98	     * True when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} other owners have already
99	     * been created for this owner's {@code registrationDate}, using the same per-day
100	     * accumulation the daily create limit enforces (the owner itself is excluded). Returns
101	     * {@code false} when the owner has no registration date (e.g. legacy seed owners).
102	     */
103	    protected boolean bulkSignupWarning(Owner owner) {
104	        LocalDate registrationDate = owner.getRegistrationDate();
105	        if (registrationDate == null) {
106	            return false;
107	        }
108	        long count = ownerRepository.findAll().stream()
109	                .filter(existing -> !existing.getId().equals(owner.getId()))
110	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
111	                .count();
112	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
113	    }
114	
115	    public abstract Owner toOwner(OwnerDto ownerDto);
116	
117	    @Mapping(target = "id", ignore = true)
118	    @Mapping(target = "pets", ignore = true)
119	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
120	
121	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
122	
123	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
124	
125	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
126	        OwnerPageDto ownerPageDto = new OwnerPageDto();
127	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
128	        ownerPageDto.setPage(ownerPage.getNumber());
129	        ownerPageDto.setSize(ownerPage.getSize());
130	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
131	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
132	        return ownerPageDto;
133	    }
134	}
